import{_ as l,o as e,c as i,a2 as r}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"批判性思维1","description":"","frontmatter":{},"headers":[],"relativePath":"idea/critical.md","filePath":"idea/critical.md","lastUpdated":null}'),t={name:"idea/critical.md"};function o(n,a,h,c,d,s){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="批判性思维1" tabindex="-1">批判性思维<a href="http://www.woshipm.com/pmd/284339.html" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#批判性思维1" aria-label="Permalink to &quot;批判性思维[1]&quot;">​</a></h1><p>《学会提问：批判性思维指南》（尼尔·布朗）</p><p>信息大爆炸时代，我们每天都会接收到很多的观点，批判性的去阅读变得异常重要。本书提供了一个批判思维的完整结构</p><p>什么是论题？什么是结论？ 理由是什么？ 哪些词语有歧义？ 什么是价值观冲突？什么是价值观假设？ 什么是描述性假设？ 推理中存在谬误吗？ 这些证据的可信度有多大？ 你发型干扰性原因了吗？ 统计数据是否具有欺骗性？ 哪些重要数据被遗漏了？ 什么结论可能是合理的？</p><h2 id="经验和方法-3" tabindex="-1">经验和方法 <a href="https://www.iamxiarui.com/?p=1416" target="_blank" rel="noreferrer">3</a> <a class="header-anchor" href="#经验和方法-3" aria-label="Permalink to &quot;经验和方法 [3]&quot;">​</a></h2><h3 id="经验和方法的区别" tabindex="-1">经验和方法的区别 <a class="header-anchor" href="#经验和方法的区别" aria-label="Permalink to &quot;经验和方法的区别&quot;">​</a></h3><ul><li>经验看似复杂实则简单，学习成本低，易学易用见效快，但是会随着环境的变化而很快过时</li><li>方法看似简单实则复杂，极其抽象不易理解和学习，但灵活，泛用性广，不易过时</li></ul><h3 id="经验和标准的关系" tabindex="-1">经验和标准的关系 <a class="header-anchor" href="#经验和标准的关系" aria-label="Permalink to &quot;经验和标准的关系&quot;">​</a></h3><ul><li>AI 领域没有经验和标准，<strong>谁活下来了，谁就是经验和标准</strong></li><li>掌握方法，可以利用自身优势创造经验</li><li>分辨经验和方法：看是否能跨场景使用</li><li>标准是成功经验的产物</li></ul><h3 id="用具有方向的思考方式取代猜测" tabindex="-1">用具有方向的思考方式取代猜测 <a class="header-anchor" href="#用具有方向的思考方式取代猜测" aria-label="Permalink to &quot;用具有方向的思考方式取代猜测&quot;">​</a></h3><ul><li>依靠方法，并不是依靠经验</li><li>结合之前的经验划定一个思考的范围</li><li>在这个范围内猜测，并通过猜测不断缩小范围</li></ul><h2 id="知道与学会-2" tabindex="-1">知道与学会 <a href="https://www.iamxiarui.com/?p=1416" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#知道与学会-2" aria-label="Permalink to &quot;知道与学会 [2]&quot;">​</a></h2><ul><li>半对半错比全错还可怕</li><li>碎片化学习需要有将所有碎片整合的能力，如果没有反而影响认知</li><li>信息利用的两要素：获取成本和鉴别成本</li></ul><p>产品经理一定要具备的能力:</p><ul><li>精确定义身边所有问题</li><li>定义的标准是可以在任何一个场景可以复现</li><li>知道是了解，学会是可复制</li></ul>',15)])])}const _=l(t,[["render",o]]);export{p as __pageData,_ as default};
